<!--
 * 消息召回管理页面
 *
 * <p>消息/通知的撤回记录管理，支持按通知ID或消息ID执行召回操作。
 *
 * @path apps/message-web/src/views/recall/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 消息召回管理（操作入口页）
 * <p>消费后端契约 RecallController（src/api/recall.ts，auto-generated by bash/gen-contract.py）：
 * recallNotification() 召回通知，recallMessage() 按日志ID召回消息，
 * recallByMsgId() 按消息ID召回消息，recallBatch() 批量召回。
 * 两个 Tab 分别对应通知召回和消息召回操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';

import { createLogger } from '@YDSZ-core/shared/utils';
import {
  ElButton,
  ElCard,
  ElForm,
  ElFormItem,
  ElInput,
  ElMessage,
  ElMessageBox,
  ElOption,
  ElSelect,
  ElTabPane,
  ElTabs,
  ElTag,
  ElTimeline,
  ElTimelineItem,
} from 'element-plus';
import { onMounted, reactive, ref } from 'vue';

import { recallBatch, recallByMsgId, recallMessage, recallNotification } from '#/api/recall';
import type { RecallRequestDTO } from '#/api/models';

defineOptions({ name: 'RecallManagement' });

const logger = createLogger('recall-management');

/** 当前激活的 Tab */
const activeTab = ref('notification');

/** 通知召回表单 */
const notificationForm = reactive({
  userId: '',
  id: '',
  bizType: '',
  bizId: '',
  recallScope: 'SINGLE',
});

/** 消息召回表单 */
const messageForm = reactive({
  logId: '',
  msgId: '',
  id: '',
  bizType: '',
  bizId: '',
  recallScope: 'SINGLE',
});

/** 召回结果日志 */
const recallLogs = ref<RecallLogItem[]>([]);

/** 加载状态 */
const executing = ref(false);

/** 召回日志项 */
interface RecallLogItem {
  type: 'notification' | 'message';
  id: string;
  time: string;
  success: boolean;
  detail: string;
}

/** 执行通知召回 */
async function handleRecallNotification(): Promise<void> {
  if (!notificationForm.id.trim()) {
    ElMessage.warning('请输入通知ID或业务ID');
    return;
  }
  try {
    await ElMessageBox.confirm(
      `确定召回通知（ID: ${notificationForm.id}）吗？召回后接收人将无法查看该通知。`,
      '召回确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消通知召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallNotification(
      { userId: notificationForm.userId.trim() || undefined },
      {
        id: notificationForm.id.trim() || undefined,
        bizType: notificationForm.bizType.trim() || undefined,
        bizId: notificationForm.bizId.trim() || undefined,
        recallScope: notificationForm.recallScope,
      },
    );
    if (success) {
      ElMessage.success('通知召回成功');
      addRecallLog('notification', notificationForm.id, true, '召回成功');
    } else {
      ElMessage.warning('召回请求已发送，但服务返回未完成');
      addRecallLog('notification', notificationForm.id, false, '服务返回未完成');
    }
  } catch (error) {
    logger.warn('通知召回失败: {}', error);
    addRecallLog('notification', notificationForm.id, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 执行消息召回（按 logId） */
async function handleRecallByLogId(): Promise<void> {
  if (!messageForm.logId.trim()) {
    ElMessage.warning('请输入消息日志ID');
    return;
  }
  try {
    await ElMessageBox.confirm(
      `确定召回消息（logId: ${messageForm.logId}）吗？`,
      '召回确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消消息召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallMessage({ logId: messageForm.logId.trim() });
    if (success) {
      ElMessage.success('消息召回成功');
      addRecallLog('message', messageForm.logId, true, '按 logId 召回成功');
    } else {
      ElMessage.warning('召回请求已发送，但服务返回未完成');
      addRecallLog('message', messageForm.logId, false, '服务返回未完成');
    }
  } catch (error) {
    logger.warn('消息召回失败: {}', error);
    addRecallLog('message', messageForm.logId, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 执行消息召回（按 msgId） */
async function handleRecallByMsgId(): Promise<void> {
  if (!messageForm.msgId.trim()) {
    ElMessage.warning('请输入消息ID');
    return;
  }
  try {
    await ElMessageBox.confirm(
      `确定召回消息（msgId: ${messageForm.msgId}）吗？`,
      '召回确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消消息召回操作');
    return;
  }
  executing.value = true;
  try {
    const success = await recallByMsgId({ msgId: messageForm.msgId.trim() });
    if (success) {
      ElMessage.success('消息召回成功');
      addRecallLog('message', messageForm.msgId, true, '按 msgId 召回成功');
    } else {
      ElMessage.warning('召回请求已发送，但服务返回未完成');
      addRecallLog('message', messageForm.msgId, false, '服务返回未完成');
    }
  } catch (error) {
    logger.warn('消息召回失败: {}', error);
    addRecallLog('message', messageForm.msgId, false, String(error));
  } finally {
    executing.value = false;
  }
}

/** 批量召回 */
async function handleRecallBatch(): Promise<void> {
  const currentForm = activeTab.value === 'notification' ? notificationForm : messageForm;
  if (!currentForm.id.trim()) {
    ElMessage.warning('请输入要召回的ID');
    return;
  }
  try {
    await ElMessageBox.confirm(
      '确定执行批量召回吗？此操作将召回匹配范围内所有消息，不可撤销。',
      '批量召回确认',
      { type: 'warning', confirmButtonText: '确认召回', cancelButtonText: '取消' },
    );
  } catch {
    logger.debug('用户取消批量召回操作');
    return;
  }
  executing.value = true;
  try {
    const count = await recallBatch({
      id: currentForm.id.trim() || undefined,
      bizType: currentForm.bizType.trim() || undefined,
      bizId: currentForm.bizId.trim() || undefined,
      recallScope: 'BATCH',
    } as RecallRequestDTO);
    ElMessage.success(`批量召回完成，共召回 ${count} 条记录`);
    addRecallLog(
      activeTab.value as 'notification' | 'message',
      currentForm.id,
      true,
      `批量召回 ${count} 条`,
    );
  } catch (error) {
    logger.warn('批量召回失败: {}', error);
    addRecallLog(
      activeTab.value as 'notification' | 'message',
      currentForm.id,
      false,
      String(error),
    );
  } finally {
    executing.value = false;
  }
}

/** 添加召回日志 */
function addRecallLog(
  type: 'notification' | 'message',
  id: string,
  success: boolean,
  detail: string,
): void {
  recallLogs.value.unshift({
    type,
    id,
    time: new Date().toLocaleTimeString(),
    success,
    detail,
  });
  // 最多保留 20 条记录
  if (recallLogs.value.length > 20) {
    recallLogs.value = recallLogs.value.slice(0, 20);
  }
}

/** 重置表单 */
function handleReset(): void {
  if (activeTab.value === 'notification') {
    notificationForm.userId = '';
    notificationForm.id = '';
    notificationForm.bizType = '';
    notificationForm.bizId = '';
    notificationForm.recallScope = 'SINGLE';
  } else {
    messageForm.logId = '';
    messageForm.msgId = '';
    messageForm.id = '';
    messageForm.bizType = '';
    messageForm.bizId = '';
    messageForm.recallScope = 'SINGLE';
  }
}

onMounted(() => {
  logger.info('消息召回管理页面已加载');
});
</script>

<template>
  <Page auto-content-height>
    <div class="recall-container p-4">
      <div class="grid grid-cols-1 gap-4 lg:grid-cols-3">
        <!-- 操作区 -->
        <div class="lg:col-span-2">
          <ElCard shadow="never">
            <ElTabs v-model="activeTab">
              <!-- 通知召回 Tab -->
              <ElTabPane label="通知召回" name="notification">
                <ElForm :model="notificationForm" label-width="100px" class="mt-4">
                  <ElFormItem label="用户ID">
                    <ElInput
                      v-model="notificationForm.userId"
                      placeholder="召回指定用户的通知（可选）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="通知ID" required>
                    <ElInput
                      v-model="notificationForm.id"
                      placeholder="站内通知ID"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="业务类型">
                    <ElInput
                      v-model="notificationForm.bizType"
                      placeholder="业务类型（可选）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="业务ID">
                    <ElInput
                      v-model="notificationForm.bizId"
                      placeholder="业务单据ID（可选）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="召回范围">
                    <ElSelect v-model="notificationForm.recallScope" class="w-full">
                      <ElOption label="单条召回" value="SINGLE" />
                      <ElOption label="批次召回" value="BATCH" />
                    </ElSelect>
                  </ElFormItem>
                  <ElFormItem>
                    <ElButton
                      v-loading="executing"
                      type="primary"
                      @click="handleRecallNotification"
                    >
                      执行召回
                    </ElButton>
                    <ElButton @click="handleReset">重置</ElButton>
                  </ElFormItem>
                </ElForm>
              </ElTabPane>

              <!-- 消息召回 Tab -->
              <ElTabPane label="消息召回" name="message">
                <ElForm :model="messageForm" label-width="100px" class="mt-4">
                  <ElFormItem label="日志ID">
                    <ElInput
                      v-model="messageForm.logId"
                      placeholder="消息日志 logId（精准召回，与消息ID二选一）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="消息ID">
                    <ElInput
                      v-model="messageForm.msgId"
                      placeholder="消息 msgId（精准召回，与日志ID二选一）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="批量ID">
                    <ElInput
                      v-model="messageForm.id"
                      placeholder="业务ID（配合批次召回使用）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="业务类型">
                    <ElInput
                      v-model="messageForm.bizType"
                      placeholder="业务类型（可选）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem label="业务ID">
                    <ElInput
                      v-model="messageForm.bizId"
                      placeholder="业务单据ID（可选）"
                      clearable
                    />
                  </ElFormItem>
                  <ElFormItem>
                    <div class="flex gap-2">
                      <ElButton
                        v-loading="executing"
                        type="primary"
                        @click="handleRecallByLogId"
                      >
                        按日志ID召回
                      </ElButton>
                      <ElButton
                        v-loading="executing"
                        type="primary"
                        @click="handleRecallByMsgId"
                      >
                        按消息ID召回
                      </ElButton>
                      <ElButton
                        v-loading="executing"
                        type="danger"
                        @click="handleRecallBatch"
                      >
                        批量召回
                      </ElButton>
                      <ElButton @click="handleReset">重置</ElButton>
                    </div>
                  </ElFormItem>
                </ElForm>
              </ElTabPane>
            </ElTabs>
          </ElCard>
        </div>

        <!-- 操作日志区 -->
        <div>
          <ElCard shadow="never">
            <h3 class="mb-3 text-base font-medium">召回操作日志</h3>
            <ElTimeline v-if="recallLogs.length > 0">
              <ElTimelineItem
                v-for="(log, index) in recallLogs"
                :key="index"
                :type="log.success ? 'success' : 'danger'"
                :timestamp="log.time"
              >
                <div class="text-sm">
                  <ElTag size="small" :type="log.type === 'notification' ? 'primary' : 'warning'">
                    {{ log.type === 'notification' ? '通知' : '消息' }}
                  </ElTag>
                  <span class="ml-2 font-mono">{{ log.id }}</span>
                </div>
                <p class="mt-1 text-xs text-gray-500">{{ log.detail }}</p>
              </ElTimelineItem>
            </ElTimeline>
            <div v-else class="py-8 text-center text-gray-400">
              暂无召回操作记录
            </div>
          </ElCard>
        </div>
      </div>
    </div>
  </Page>
</template>
